      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "किंचाङ्गीकृतमुत्सृजन्न मनसा श्लाघ्यो जनो लज्जते",
          "end": "line"
        },
        {
          "n": 2,
          "text": "निर्वाहः प्रतिपन्नवस्तुषु सतामेतद्धि गोत्रव्रतम् ॥ ७ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "को न याति वशं लोके मुखे पिण्डेन पूरितः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "मृदङ्गो मुखलेपेन करोति मधुरध्वनिम् ॥ ८ ॥",
          "end": "space"
        },
        {
          "n": 3,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "क्षुद्राः सन्ति सहस्रशः स्वभरणव्यापारमात्रोद्यताः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्वार्थो यस्य पदार्थ एव परमो नैकः सतामग्रणीः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "दुःपूरोदरपूरणाय पिबति स्रोतःपतिं वाडवो",
          "end": "line"
        },
        {
          "n": 4,
          "text": "जीमूतस्तु निदाघसंभृतजगत्संतापविच्छित्तये ॥ ९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दूरादर्थं घटयति नवं दूरतश्चापशब्दं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "त्यक्त्वा भूयो भवति निरतः सत्सभारञ्जनेषु ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मन्दंमन्दं रचयति पदं लोकचित्तानुवृत्त्या",
          "end": "line"
        },
        {
          "n": 4,
          "text": "कामं मन्त्री कविरिव सदा खेदभारैरमुक्तः ॥ १० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दैवेन प्रभुणा स्वयं जगति यद्यस्य प्रमाणीकृतं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तत्तस्योपनमेन्मनागपि महान्नेवाश्रयः कारणम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "सर्वाशापरिपूरके जलधरे वर्षत्यपि प्रत्यहं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "सूक्ष्मा एव पतन्ति चातकमुखे द्वित्राः पयोबिन्दवः ॥ ११ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "परिचरितव्याः सन्तो यद्यपि कथयन्ति न सदुपदेशम् ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "यास्त्वेषां स्वैरकथास्ता एव भवन्ति शास्त्राणि ॥ १२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
